import{_ as t,c as a,o as n,ag as o}from"./chunks/framework.DZ_cNctr.js";const i="/docs/screenshots/phenix-plate-overview.png",s="/docs/screenshots/phenix-plate-panel.png",l="/docs/screenshots/phenix-plate-channels.png",r="/docs/screenshots/phenix-save-manifest.png",w=JSON.parse('{"title":"Opera Phenix plates","description":"Open an Opera Phenix or Harmony plate straight from its index, on the web, in an S3 bucket or on your disk. Move through every well and field without converting anything.","frontmatter":{"title":"Opera Phenix plates","description":"Open an Opera Phenix or Harmony plate straight from its index, on the web, in an S3 bucket or on your disk. Move through every well and field without converting anything."},"headers":[],"relativePath":"guides/opera-phenix-plates.md","filePath":"guides/opera-phenix-plates.md"}'),h={name:"guides/opera-phenix-plates.md"};function p(d,e,c,m,f,g){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="opera-phenix-plates" tabindex="-1">Opera Phenix plates <a class="header-anchor" href="#opera-phenix-plates" aria-label="Permalink to &quot;Opera Phenix plates&quot;">​</a></h1><p>Find Nuclei Viewer opens plates exported by Harmony from an Opera Phenix, straight from their index. Nothing is converted and nothing is uploaded. The Opera Phenix plates of the Cell Painting Gallery open this way, such as the JUMP Cell Painting pilot plate CPJUMP1.</p><p><img src="'+i+`" alt="JUMP Cell Painting plate BR00116991 open in field view on well A/1, field 0, with Alexa 488 and HOECHST 33342 cells on the canvas, the Field / Well / Plate toggle with Well and Plate greyed out, the Opera Phenix note, the well navigator reading Well A/1, 1 of 384, and the 384-well picker" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p>Other formats the viewer opens are listed in <a href="./supported-formats.html">Supported Formats</a>.</p><h2 id="what-opens" tabindex="-1">What opens <a class="header-anchor" href="#what-opens" aria-label="Permalink to &quot;What opens&quot;">​</a></h2><p>A Harmony export is an <code>Index.idx.xml</code> file next to one TIFF per field, plane, timepoint and channel. The viewer reads the index (the Harmony v5 format) and loads the TIFFs as you look at them.</p><p>The files can sit at any web address that lets the browser read them, such as a public S3 bucket, or in a folder on your disk.</p><h2 id="opening-a-plate-from-the-web" tabindex="-1">Opening a plate from the web <a class="header-anchor" href="#opening-a-plate-from-the-web" aria-label="Permalink to &quot;Opening a plate from the web&quot;">​</a></h2><p>Open the <strong>Open</strong> dialog, choose <strong>From URL</strong> and paste one of these:</p><ul><li>the folder that holds the plate (the measurement folder),</li><li>the folder that holds <code>Index.idx.xml</code> (often <code>Images/</code>),</li><li>or the address of <code>Index.idx.xml</code> itself.</li></ul><p>An <code>https://</code> address and an <code>s3://</code> address both work. Here is a JUMP Cell Painting plate in both forms:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://cellpainting-gallery.s3.amazonaws.com/cpg0000-jump-pilot/source_4/images/2020_11_04_CPJUMP1/images/BR00116991__2020-11-05T19_51_35-Measurement1/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>s3://cellpainting-gallery/cpg0000-jump-pilot/source_4/images/2020_11_04_CPJUMP1/images/BR00116991__2020-11-05T19_51_35-Measurement1/</span></span></code></pre></div><p>A bucket name with a dot in it works as <code>s3://</code> in us-east-1. In any other region, paste its regional https address instead: <code>https://s3.&lt;region&gt;.amazonaws.com/&lt;bucket&gt;/...</code>.</p><h2 id="opening-a-plate-from-disk" tabindex="-1">Opening a plate from disk <a class="header-anchor" href="#opening-a-plate-from-disk" aria-label="Permalink to &quot;Opening a plate from disk&quot;">​</a></h2><p>Open the <strong>Open</strong> dialog, go to <strong>Local Files</strong> and click <strong>Choose Data Folder</strong>. Pick the measurement folder or the folder that holds the index, whatever its name. Nothing leaves your computer.</p><p>Folders open in Chrome and Edge, as for any dataset folder. Safari and Firefox cannot open folders. See <a href="./local-files.html">Local Files</a> for the details.</p><h2 id="what-to-expect" tabindex="-1">What to expect <a class="header-anchor" href="#what-to-expect" aria-label="Permalink to &quot;What to expect&quot;">​</a></h2><p>The plate opens as soon as the viewer has read the start of the index, about 1 MB. The whole index can be tens of megabytes. A progress line counts the megabytes while it reads.</p><p>The second time, the plate opens at once. The viewer keeps what it learned in the browser&#39;s storage. <strong>Clear All Data</strong> on the start screen removes it.</p><p>The viewer reads only the start of the index. If an image is missing or cannot be read, that channel is left out of that field and the other channels still show.</p><h2 id="moving-through-the-plate" tabindex="-1">Moving through the plate <a class="header-anchor" href="#moving-through-the-plate" aria-label="Permalink to &quot;Moving through the plate&quot;">​</a></h2><p>The plate opens in field view on the first well that holds images. The panel is titled with the plate name from the index, such as BR00116991. The well navigator steps through the wells that are present, and the well picker below it jumps to any of them. Wells with no images are skipped.</p><p>When the plate has several fields, Z planes or timepoints, the field dropdown and the Z and T sliders move between them. The <a href="./hcs-plates.html">HCS Plates</a> guide covers the navigator and picker.</p><p><img src="`+s+'" alt="The Navigation tab of plate BR00116991: Field active and Well and Plate greyed out, the note reading Opera Phenix plate: one resolution per field, so Field view only, the well navigator on Well A/1 with the Field 0 dropdown and 1 of 384, and the 384-well picker, 16 by 24, with every well present" style="max-width:425px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h2 id="why-there-is-no-plate-or-well-view" tabindex="-1">Why there is no plate or well view <a class="header-anchor" href="#why-there-is-no-plate-or-well-view" aria-label="Permalink to &quot;Why there is no plate or well view&quot;">​</a></h2><p>Fast overviews come from a resolution pyramid. OME-Zarr stores each image several times: at full resolution, then at half, a quarter, and smaller, each cut into small tiles. A plate overview reads only the small levels, a tiny part of the data, and zooming in fetches the detail tiles just for what is on screen.</p><p>A Harmony export has no pyramid. Each field and channel is one TIFF at full resolution, about 2.5 MB on CPJUMP1. An overview of that plate would mean downloading all 27,648 TIFFs, around 70 GB, and shrinking them in the browser. So these plates open one field at a time: eight channels for a field of CPJUMP1, about 20 MB.</p><p>Want plate and well views? Convert the plate to OME-Zarr. <a href="https://www.find-nuclei.com/blog/how-to-convert-to-ome-zarr" target="_blank" rel="noreferrer">How to Convert Any Microscopy File to OME-Zarr</a> shows how.</p><p>Field view works as for any image: zoom, pan, channels, contrast.</p><h2 id="channels-and-colours" tabindex="-1">Channels and colours <a class="header-anchor" href="#channels-and-colours" aria-label="Permalink to &quot;Channels and colours&quot;">​</a></h2><p>Channels take their names from the index. Each one is coloured by its emission wavelength. Brightfield channels are grey and start switched off, so the first view shows the fluorescence. Turn them on in the channel panel. The <a href="./channels.html">Channels</a> guide covers the rest.</p><p><img src="'+l+'" alt="View Options, Channels (8), on plate BR00116991: Alexa 647 and Alexa 568 switched off, 488 long, Alexa 488 and HOECHST 33342 switched on with their contrast sliders, and Brightfield H, Brightfield L and Brightfield switched off" style="max-width:392px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h2 id="the-plate-manifest" tabindex="-1">The plate manifest <a class="header-anchor" href="#the-plate-manifest" aria-label="Permalink to &quot;The plate manifest&quot;">​</a></h2><p>Behind every Harmony plate the viewer builds a plate manifest: a small JSON file that names the plate, its wells, fields, planes, timepoints and channels, the image size and pixel size, and the file name of every image.</p><p>To keep one, open <strong>Info</strong> in the toolbar and click <strong>Save plate manifest</strong>. The viewer first reads the whole index, which can take a minute on a large plate, and then saves a complete manifest.</p><p><img src="'+r+'" alt="The Image Information dialog for plate BR00116991, series A/1/0: 1080 by 1080 pixels, uint16, 0.5980 µm pixels, 8 channels, 1 resolution, stored remotely at an s3:// address in the Cell Painting Gallery, with the Save plate manifest button at the bottom" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p>A saved manifest opens the plate on its own, from its web address in <strong>From URL</strong>. The plate opens at once, with no index to read.</p><ul><li>A manifest saved from a web plate names its images folder, so it can sit anywhere on the web.</li><li>A manifest saved from a folder on disk names no images folder. Put it in the <code>Images/</code> folder next to the TIFFs, then open its address. A manifest file does not open from disk; open the folder instead.</li></ul><p>The format is published as a JSON Schema: <a href="https://find-nuclei.github.io/schemas/plate-manifest/v1.json" target="_blank" rel="noreferrer">https://find-nuclei.github.io/schemas/plate-manifest/v1.json</a>.</p><h2 id="publishing-a-plate" tabindex="-1">Publishing a plate <a class="header-anchor" href="#publishing-a-plate" aria-label="Permalink to &quot;Publishing a plate&quot;">​</a></h2><p>Showing a plate with a paper, a figure or a blog post? Publish its manifest. A published manifest opens the plate without reading its index, so your readers see it at once.</p><ol><li><p>Build the manifest. In the viewer, open the plate and click <strong>Save plate manifest</strong> in <strong>Info</strong>. Or build it from the command line in <code>find-nuclei-viewer-js</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm run build:plate-manifest -- s3://cellpainting-gallery/cpg0000-jump-pilot/source_4/images/2020_11_04_CPJUMP1/images/BR00116991__2020-11-05T19_51_35-Measurement1/</span></span></code></pre></div><p>Give it the measurement folder or the address of <code>Index.idx.xml</code>, <code>https://</code> or <code>s3://</code>. It reads the whole index once and writes <code>BR00116991.plate-manifest.json</code>. Add <code>--out &lt;file&gt;</code> to pick the name.</p></li><li><p>Host the file next to your page, on any web server or on GitHub. The images stay where they are. The manifest points at them by their full address.</p></li><li><p>Open it in the viewer by its URL, in <strong>From URL</strong>. A link to the viewer works too: <code>https://find-nuclei.github.io/?url=&lt;manifest URL&gt;</code>.</p></li></ol><p>The bucket that holds the images must let browsers read it, as for any plate on the web.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>No flat-field correction yet. Images show as recorded.</li><li>Treatment names from Harmony&#39;s assay layout are not shown yet. Wells show their position only.</li><li>Zipped Harmony exports do not open. Unzip them into a folder first.</li><li>The embedded viewer does not open these plates. Use the full viewer.</li></ul>',45)])])}const b=t(h,[["render",p]]);export{w as __pageData,b as default};
